SELECT COUNT(1) FROM friends
WHERE owner_account_id = #{ownerAccountId}
  AND friend_account_id = #{friendAccountId}

SELECT COUNT(1) FROM friend_requests
WHERE from_account_id = #{fromAccountId}
  AND to_account_id = #{toAccountId}
  AND status = 'PENDING'

SELECT id, from_account_id, to_account_id, status, created_at, handled_at
FROM friend_requests
WHERE id = #{requestId}
  AND to_account_id = #{toAccountId}
  AND status = 'PENDING'

mapper.update:
UPDATE friend_requests
SET status = #{status}, handled_at = #{handledAt}
WHERE id = #{requestId}
  AND status = 'PENDING'
